import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"同人於野","description":"周易集解 - 同人於野","frontmatter":{"title":"同人於野","description":"周易集解 - 同人於野"},"headers":[],"relativePath":"zh/classics/jijie/013.md","filePath":"zh/classics/jijie/013.md"}'),l={name:"zh/classics/jijie/013.md"};function n(d,a,p,t,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="同人於野" tabindex="-1">同人於野 <a class="header-anchor" href="#同人於野" aria-label="Permalink to “同人於野”">​</a></h1><h2 id="同人於野-1" tabindex="-1">同人於野 <a class="header-anchor" href="#同人於野-1" aria-label="Permalink to “同人於野”">​</a></h2><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>同人於野，亨。利涉大川，利君子貞。</p><h2 id="卦辞注" tabindex="-1">卦辞注 <a class="header-anchor" href="#卦辞注" aria-label="Permalink to “卦辞注”">​</a></h2><p>《序卦》曰：物不可以終否，故受之以同人。</p><p>崔憬曰：否終則傾，故同於人。通而利涉矣。</p><p>鄭玄曰：乾為天，離為火。卦體有巽，巽為風。天在上，火炎上而從之，是其性同於天也。火得風，然後炎上益熾，是猶人君在上施政教，使天下之人和同而事之。以是為人和同者，君之所為也。故謂之同人。風行無所不遍，遍則會通之德大行，故曰「同人於野，亨」。</p><p>崔憬曰：以離文明，而合乾健。九五中正，同人於二，為能通天下之志，故能「利涉大川，利君子之貞」。</p><h2 id="彖" tabindex="-1">彖 <a class="header-anchor" href="#彖" aria-label="Permalink to “彖”">​</a></h2><p>《彖》曰：同人，柔得位得中，而應乎乾，曰同人。同人曰：同人於野，亨，利涉大川，乾行也。文明以健，中正而應，君子正也。唯君子為能通天下之志。</p><h2 id="彖传注" tabindex="-1">彖传注 <a class="header-anchor" href="#彖传注" aria-label="Permalink to “彖传注”">​</a></h2><p>《九家易》曰：謂乾舍於離，同而為日。天日同明，以照於下。君子則之，上下同心，故曰同人。</p><p>蜀才曰：此本夬卦。九二升上，上六降二，則「柔得位得中，而應乎乾」。下奉上之象，義同於人，故曰同人。</p><p>虞翻曰：旁通師卦。巽為同，乾為野。師震為人。二得中應乾。故曰「同人於野，亨」。此孔子所以明嫌表微。師震為夫，巽為婦，所謂二人同心。故不稱君臣、父子、兄弟、朋友，而故言人耳。乾四上失位，變而體坎，故曰「利涉大川，乾行也」。</p><p>侯果曰：九二升上，上為郊野，是同人於野而得通者，由乾爻上行耳。故特曰乾行也。</p><p>何妥曰：離為文明，乾為剛健。健非尚武，乃以文明。應不以邪，乃以中正。故曰利君子貞也。</p><p>虞翻曰：唯，獨也。四變成坎。坎為通、為志。故能通天下之志。謂五以類族辯物，聖人作而萬物覩。</p><p>崔憬曰：君子謂九五，能捨己同人，以通天下之志。若九三、九四，以其人臣，則不當矣。故爻辭不言同人也。</p><h2 id="象" tabindex="-1">象 <a class="header-anchor" href="#象" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：天與火，同人。君子以類族辯物。</p><h2 id="象传注" tabindex="-1">象传注 <a class="header-anchor" href="#象传注" aria-label="Permalink to “象传注”">​</a></h2><p>荀爽曰：乾舍於離，相與同居，故曰同人也。</p><p>虞翻曰：君子謂乾。師坤為類，乾為族。辯，別也。乾，陽物。坤，陰物。體姤，天地相遇，品物咸章，以乾照坤。故以類族辯物。謂方以類聚，物以群分。孔子曰：君子和而不同，故於同人象見，以類族辯物也。</p><h2 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h2><p>初九，同人於門，無咎。</p><h2 id="初九注" tabindex="-1">初九注 <a class="header-anchor" href="#初九注" aria-label="Permalink to “初九注”">​</a></h2><p>虞翻曰：乾為門，謂同於四，四變應初，故無咎也。</p><h2 id="象-1" tabindex="-1">象 <a class="header-anchor" href="#象-1" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：出門同人，又誰咎也。</p><h2 id="象传注-1" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-1" aria-label="Permalink to “象传注”">​</a></h2><p>崔憬曰：剛而無應，比二以柔，近同於人，出門之象，又誰咎矣。</p><p>案：初九震爻，帝出乎震。震為大塗，又為日門，出門之象也。</p><h2 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h2><p>六二，同人於宗，吝。</p><h2 id="六二注" tabindex="-1">六二注 <a class="header-anchor" href="#六二注" aria-label="Permalink to “六二注”">​</a></h2><p>荀爽曰：宗者，眾也。三據二陰，二與四同功，五相應，初相近，上下眾陽，皆欲與二為同，故曰同人於宗也。陰道貞靜，從一而終，今宗同之，故吝也。</p><h2 id="象-2" tabindex="-1">象 <a class="header-anchor" href="#象-2" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：同人於宗，吝道也。</p><h2 id="象传注-2" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-2" aria-label="Permalink to “象传注”">​</a></h2><p>侯果曰：宗，謂五也。二為同人之主，和同者之所仰也。有應在五，唯同於五，過五則否，不能大同於人，則為主之德吝狹矣。所同雖吝，亦妻臣之道也。</p><h2 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h2><p>九三，伏戎於莽，升其高陵，三歲不興。</p><h2 id="九三注" tabindex="-1">九三注 <a class="header-anchor" href="#九三注" aria-label="Permalink to “九三注”">​</a></h2><p>虞翻曰：巽為伏，震為草莽，離為戎。謂四變時三在坎中，隱伏自藏，故伏戎於莽也。巽為高，師震為陵，以巽股升其高陵。爻在三。乾為歲。興，起也。動不失位，故三歲不興也。</p><h2 id="象-3" tabindex="-1">象 <a class="header-anchor" href="#象-3" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：伏戎於莽，敵剛也。三歲不興，安行也。</p><h2 id="象传注-3" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-3" aria-label="Permalink to “象传注”">​</a></h2><p>崔憬曰：與二相比，欲同人焉。盜憎其主，而忌於五，所以隱兵於野，將以襲之，故曰伏戎於莽。五既居上，故曰升其高陵。一爻為一年，自三至五，頻遇剛敵，故三歲不興，安可行也。</p><p>案：三互離巽，巽為草木，離為戈兵，伏戎於莽之象也。</p><h2 id="九四" tabindex="-1">九四 <a class="header-anchor" href="#九四" aria-label="Permalink to “九四”">​</a></h2><p>九四，乘其墉，弗克攻，吉。</p><h2 id="九四注" tabindex="-1">九四注 <a class="header-anchor" href="#九四注" aria-label="Permalink to “九四注”">​</a></h2><p>虞翻曰：巽為墉，四在巽上，故乘其墉。變而承五。體訟，乾剛在上。故弗克攻則吉也。</p><h2 id="象-4" tabindex="-1">象 <a class="header-anchor" href="#象-4" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：乘其墉，義弗克也。其吉，則困而反則也。</p><h2 id="象传注-4" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-4" aria-label="Permalink to “象传注”">​</a></h2><p>王弼曰：處上攻下，力能乘墉者也。履非其位，與三爭二。二自應五，三非犯己，攻三求二，尤而效之。違義傷禮，眾所不與。勢雖乘墉，義終弗克，而得吉者，以困而反正則也。</p><h2 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h2><p>九五，同人先號咷而後笑，大師克相遇。</p><h2 id="九五注" tabindex="-1">九五注 <a class="header-anchor" href="#九五注" aria-label="Permalink to “九五注”">​</a></h2><p>虞翻曰：應在二。巽為號咷，乾為先，故先號咷。師震在下，故後笑。震為後笑也。乾為大，同人反師，故大師。二至五，體姤遇也，故相遇。</p><h2 id="象-5" tabindex="-1">象 <a class="header-anchor" href="#象-5" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：同人之先，以中直也。大師相遇，言相剋也。</p><h2 id="象传注-5" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-5" aria-label="Permalink to “象传注”">​</a></h2><p>侯果曰：乾德中直，不私於物，欲天下大同，方始同二矣。三四失義，而近據之，未獲同心，故先號咷也。時須同好，寇阻其途，以言相剋，然後始相遇，故笑也。</p><p>《九家易》曰：乾為言。</p><h2 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h2><p>上九，同人於郊，無悔。</p><h2 id="上九注" tabindex="-1">上九注 <a class="header-anchor" href="#上九注" aria-label="Permalink to “上九注”">​</a></h2><p>虞翻曰：乾為郊。失位無應，與乾上九同義，當有悔。同心之家。故無悔。</p><h2 id="象-6" tabindex="-1">象 <a class="header-anchor" href="#象-6" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：同人於郊，志未得也。</p><h2 id="象传注-6" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-6" aria-label="Permalink to “象传注”">​</a></h2><p>侯果曰：獨處於外，同人於郊也。不與內爭，無悔吝也。同人之時，唯同於郊，志未得也。</p>',75)])])}const m=e(l,[["render",n]]);export{b as __pageData,m as default};
